mapper.select:
SELECT exercise_date AS date, COALESCE(SUM(actual_seconds), 0) AS total
FROM exercise_record
WHERE user_id = #{userId}
  AND status = 2
  AND exercise_date BETWEEN #{startDate} AND #{endDate}
GROUP BY exercise_date

SELECT
    SUM(CASE WHEN actual_seconds >= (SELECT daily_target_minutes * 60 FROM exercise_plan WHERE plan_id = (
        SELECT plan_id FROM exercise_plan WHERE user_id = #{userId} AND status = 1 LIMIT 1
    )) THEN 1 ELSE 0 END) AS doneDays,
    SUM(CASE WHEN actual_seconds > 0 AND actual_seconds < (SELECT daily_target_minutes * 60 FROM exercise_plan WHERE plan_id = (
        SELECT plan_id FROM exercise_plan WHERE user_id = #{userId} AND status = 1 LIMIT 1
    )) THEN 1 ELSE 0 END) AS insufficientDays
FROM exercise_record
WHERE user_id = #{userId}
  AND exercise_date BETWEEN #{startDate} AND #{endDate}
  AND status = 2

SELECT COUNT(DISTINCT exercise_date)
FROM exercise_record
WHERE user_id = #{userId}
  AND status = 2
  AND exercise_date >= #{sinceDate}

SELECT COUNT(DISTINCT user_id)
FROM exercise_record
WHERE status = 2 AND exercise_date >= #{sinceDate}
